require('dotenv').config();
process.on('uncaughtException', ...);
process.on('unhandledRejection', ...);

const express = require('express');
const cors = require('cors');
const jwt = require('jsonwebtoken');
const mongoose = require('mongoose');
const cron = require('node-cron');
const { runSync } = require('./controllers/deviceController');
const routes = require('./routes/route');

const app = express();
app.use(cors());
app.use(express.json());

mongoose.connect(...)...

const auth = (req, res, next) => {...};

app.use('/api', routes(auth));

// ---- Auto sync ----
const mins = Math.max(1, Number(process.env.SYNC_MINUTES || 5));
cron.schedule(...)

app.listen(...)
```

Note: server.js still requires jwt for auth. Good.

Cron handler: `if (syncPromise) return;` — syncPromise was module-level in server.js. Now it's in deviceController. Behavior: runSync() itself dedupes concurrent syncs, so `if (syncPromise) return` skip-if-running needs access. Export a `isSyncing()` from deviceController or just call runSync() which returns the in-flight promise. Original: if a manual sync is running, cron tick skips entirely (doesn't await). With runSync() dedupe, cron tick would await the running sync and log its result — slightly different logging, not functionality. To be faithful, export `isSyncing`? Hmm. Add to deviceController:

```js
const isSyncing = () => Boolean(syncPromise);
```
and cron:
```js
if (isSyncing()) return;
try { console.log('Auto sync:', await runSync()); } catch ...
```
That preserves exactly. I'll export isSyncing too. Wait, but "do not create unnecessary" ... it's needed for behavior preservation. Fine.

Now `runSync` in deviceController sets statusCache on success — same.

